module ewcharge_mod 
  use types
  use nf_mod
  use, intrinsic :: iso_c_binding
  implicit none

  private
    interface
      function get_Q() bind(C, name="ewcharge_mod_Q")
        import :: c_ptr, c_double
        type(c_ptr) :: get_Q
      end function get_Q

      function get_tau() bind(C, name="ewcharge_mod_tau")
        import :: c_ptr, c_double
        type(c_ptr) :: get_tau
      end function get_tau
    end interface

  public :: Q, tau, ewcharge_mod_init, ewcharge_mod_finalize
  real(c_double), dimension(:), pointer :: Q => null(), tau => null()

contains
  subroutine ewcharge_mod_init()
    implicit none
    real(c_double), dimension(:), pointer :: fptr => null()

    allocate(Q(-nf:nf), tau(-nf:nf))
    call c_f_pointer(get_Q(), fptr, [2*nf + 1])
    Q(-nf:nf) => fptr(1:2*nf+1)
    fptr => null()
    call c_f_pointer(get_tau(), fptr, [2*nf + 1])
    tau(-nf:nf) => fptr(1:2*nf+1)
    fptr => null()
  end subroutine ewcharge_mod_init

  subroutine ewcharge_mod_finalize()
    implicit none
    nullify(Q,tau)
  end subroutine ewcharge_mod_finalize

end module

